#!/usr/bin/env node
/* Real-control provider career acceptance recorder. Writes only under /tmp. */
const playwright=require('playwright-core');
const fs=require('node:fs');
const path=require('node:path');
const http=require('node:http');
const assert=require('node:assert/strict');
const crypto=require('node:crypto');
const {execFileSync}=require('node:child_process');
const productRecipes=require(path.resolve(__dirname,'../src/game/23-provider-products.js')).recipes;

const ROOT=path.resolve(__dirname,'..');
const ENGINE=process.env.SOC_PROVIDER_BROWSER_ENGINE||'chromium';
if(!['chromium','firefox','webkit'].includes(ENGINE))throw new Error('Unsupported SOC_PROVIDER_BROWSER_ENGINE: '+ENGINE);
const BROWSER=process.env.SOC_PROVIDER_BROWSER_EXECUTABLE||(ENGINE==='chromium'?process.env.CHROMIUM_PATH:undefined);
const OUT=path.resolve(process.env.SOC_PROVIDER_BROWSER_OUT||'/tmp/soc-provider-gameplay-browser');
if(!OUT.startsWith('/tmp/'))throw new Error('SOC_PROVIDER_BROWSER_OUT must be under /tmp');
const plans=[{plan:'swift',viewport:{width:1366,height:768},id:'swift-desktop'},{plan:'steady',viewport:{width:390,height:844},id:'steady-mobile'},{plan:'swift',viewport:{width:390,height:844},id:'swift-mobile'},{plan:'steady',viewport:{width:1366,height:768},id:'steady-desktop'}];
const report={startedAt:new Date().toISOString(),runId:new Date().toISOString().replace(/[^0-9]/g,''),status:'running',browser:null,engine:ENGINE,playwright:require('playwright-core/package.json').version,journeys:[],errors:[],scope:'Visible-control provider careers using the actual browser clock at 8x. State reads are observational; no state or clock mutation from evaluate.'};
let server=null,browser=null,serverLog='';
function sourceFiles(dir){return fs.readdirSync(path.join(ROOT,dir),{withFileTypes:true}).flatMap(entry=>{const rel=path.posix.join(dir,entry.name);return entry.isDirectory()?sourceFiles(rel):entry.isFile()?[rel]:[];}).sort();}
const SOURCE_FIXED_INPUTS=['package.json','package-lock.json','scripts/build.js','scripts/lib/page.js','scripts/lib/dict.js','scripts/provider-browser.js'];
function sourceManifest(previousInputs=[]){
 const errors=[],scan=dir=>{try{return fs.readdirSync(path.join(ROOT,dir),{withFileTypes:true}).flatMap(entry=>{const rel=path.posix.join(dir,entry.name);return entry.isDirectory()?scan(rel):entry.isFile()?[rel]:[];});}catch(error){errors.push({operation:'list',path:dir,code:error.code||error.name});return [];}};
 const inventory=[...new Set([...scan('src'),...scan('content'),...scan('site'),...SOURCE_FIXED_INPUTS])].sort();
 const hashes=Object.fromEntries([...new Set([...previousInputs,...inventory])].sort().map(file=>{try{return [file,crypto.createHash('sha256').update(fs.readFileSync(path.join(ROOT,file))).digest('hex')];}catch(error){errors.push({operation:'read',path:file,code:error.code||error.name});return [file,null];}}));
 let head=null;try{head=execFileSync('git',['rev-parse','HEAD'],{cwd:ROOT,encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();}catch(error){errors.push({operation:'git-head',code:error.code||error.name});}
 return {head,inventory,hashes,errors};
}
function finishSourceEvidence(target,after){
 const before=target.source;if(!before){target.source={noSourceDrift:false,errors:[{operation:'initial-manifest',code:'NOT_RECORDED'}],hashesAfter:after.hashes,inventoryAfter:after.inventory,errorsAfter:after.errors};if(target.status==='passed')target.status='diagnostic-passed';return;}
 const initial=before.inventory||Object.keys(before.hashes||{}),final=after.inventory||Object.keys(after.hashes||{});
 before.headAfter=after.head;before.hashesAfter=after.hashes;before.inventoryAfter=final;before.errorsAfter=after.errors;
 before.addedInputs=final.filter(file=>!initial.includes(file));before.removedInputs=initial.filter(file=>!final.includes(file));
 before.changedInputs=[...new Set([...initial,...final])].filter(file=>before.hashes[file]!==after.hashes[file]||after.hashes[file]===null);
 before.noSourceDrift=!before.errors?.length&&!after.errors?.length&&before.head!==null&&before.head===after.head&&!before.addedInputs.length&&!before.removedInputs.length&&!before.changedInputs.length;
 if(!before.noSourceDrift&&target.status==='passed')target.status='diagnostic-passed';
}
function writeFinalReport(){
 try{finishSourceEvidence(report,sourceManifest(report.source?.inventory||Object.keys(report.source?.hashes||{})));}catch(error){report.finalizationErrors??=[];report.finalizationErrors.push({operation:'final-manifest',error:String(error.stack||error)});report.source??={};report.source.noSourceDrift=false;if(report.status==='passed')report.status='diagnostic-passed';}
 if(report.status!=='passed'||report.source?.noSourceDrift!==true)process.exitCode=1;
 report.serverLog=serverLog;report.finishedAt=new Date().toISOString();report.reportFile=path.join(OUT,`provider-browser-${report.runId}.json`);
 fs.mkdirSync(OUT,{recursive:true});fs.writeFileSync(report.reportFile,JSON.stringify(report,null,2)+'\n');
 try{fs.writeFileSync(path.join(OUT,'provider-browser-latest.txt'),report.reportFile+'\n');}catch(error){console.error('Browser latest pointer could not be written: '+(error.code||error.name));process.exitCode=1;}
 console.log(JSON.stringify({status:report.status,output:OUT,report:report.reportFile,noSourceDrift:report.source?.noSourceDrift===true,error:report.error?.split('\n')[0],journeys:report.journeys.map(x=>({id:x.id,status:x.status}))}));
}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function startServer(){
 require('node:child_process').execFileSync(process.execPath,['scripts/build.js'],{cwd:ROOT,stdio:'inherit'});
 const built=path.join(ROOT,'_site');if(!fs.existsSync(path.join(built,'index.html')))throw new Error('Compiled static artifact missing after build.');
 const files=sourceFiles('_site'),hashes=Object.fromEntries(files.map(file=>[file,crypto.createHash('sha256').update(fs.readFileSync(path.join(ROOT,file))).digest('hex')]));
 const site=path.join(OUT,'provider-browser-site');fs.rmSync(site,{recursive:true,force:true});fs.cpSync(built,site,{recursive:true});report.artifact={directory:site,files:files.length,hashes};
 server=http.createServer(require(path.join(ROOT,'scripts/serve')).handler(site,{basePath:'/provider-prefix/'}));await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',resolve);});
 const address=`http://127.0.0.1:${server.address().port}/provider-prefix/`;serverLog=`Built static artifact ${site} at ${address}`;return address;
}
async function readState(page){return page.evaluate(()=>{const s=SCP.state,p=s.providerCampaign,model=providerModel(),child=s.portfolio.customers.find(c=>c.id==='starter-customer')?.root;return {clock:s.clock,revision:s.revision,cash:s.business.balance.cash,status:p.status,scenario:p.scenario,segmentHistory:structuredClone(p.segmentHistory||[]),missionStatus:p.missionStatus,mission:structuredClone(p.mission),customers:p.customers.map(x=>{const shown=model.customers.find(c=>c.id===x.id);return {id:x.id,name:x.name,planId:x.planId,status:x.status,stages:Object.fromEntries(Object.entries(x.stages).map(([k,v])=>[k,v&&v.status])),outcome:structuredClone(x.outcome),history:structuredClone(x.history),continuity:structuredClone(shown?.continuity||null)};}),projects:p.projects.map(x=>({id:x.id,kind:x.kind,operationId:x.operationId,status:x.status,dueAt:x.dueAt})),incidents:p.incidents.map(x=>({id:x.id,status:x.status,kind:x.kind,resource:x.resource})),externalDisconnectedResolved:s.portfolio.customers.some(c=>c.root.interactions.some(i=>i.phase==='resolved'&&i.providerContext?.connected===false)),completedJobs:p.jobs.filter(j=>j.status==='completed').length,deployments:(child?.products?.deployments||[]).map(d=>({id:d.id,effective:d.effective,status:d.provisioning?.status})),migrations:structuredClone(child?.operations?.migrations||[]),periodHistory:structuredClone(p.periodHistory),events:p.events.map(x=>({at:x.at,code:x.code}))};});}
async function snap(page,journey,name){await page.screenshot({path:path.join(OUT,journey.id,`${name}.png`),fullPage:true});}
async function click(page,selector){const x=page.locator(`${selector}:visible`).first();await x.waitFor({state:'visible',timeout:15000});await x.click();}
async function selectMapCustomer(page,customerId='starter-customer'){
 // Explicitly dismiss overlays, then select the world object. Focus never owns a sheet.
 for(const selector of ['.provider-modal [data-provider-action="drawer-close"]','.provider-inspector [data-provider-action="close-inspector"]','.provider-rail-body [data-provider-action="drawer-close"]']){
  const close=page.locator(selector+':visible').first();if(await close.isVisible())await close.click();
 }
 await click(page,`.provider-map-node[data-provider-action="select-customer"][data-id="${customerId}"]`);
 await page.locator('.provider-inspector').waitFor({state:'visible'});
}
async function openOperation(page,operationId,customerId='starter-customer'){
 await selectMapCustomer(page,customerId);
 const selector=`.provider-inspector [data-provider-action="operation"][data-operation="${operationId}"][data-id="${customerId}"]`;
 await click(page,selector);
 await page.locator('[data-provider-action="confirm-quote"]:visible').first().waitFor({state:'visible'});
}
async function startNew(page,scenario){
 await click(page,'[data-provider-action="show-new-game"]');const form=page.locator('[data-provider-form="new-game"]');await form.locator('[name=providerName]').fill(`Orchard ${scenario.plan} ${scenario.id}`);await form.locator('[name=market]').selectOption('au-sydney');await form.locator('[name=difficulty]').selectOption('normal');await form.locator('[name=scenario]').selectOption('smb');await form.locator('button[type=submit]').click();
 await page.waitForFunction(()=>!!SCP.state?.providerCampaign&&SCP.locked, null,{timeout:20000});
}
