  await page.waitForFunction(()=>SCP.state.providerCampaign.missionStatus==='won',null,{timeout:15000});state=await readState(page);assert.equal(state.missionStatus,'won');assert.equal(state.customers[0].planId,spec.plan);assert.equal(state.customers.length,2);assert.equal(state.customers[1].stages.base,'provisioning','the win records a funded next base order, not delivered service');assert.ok(state.periodHistory.filter(x=>x.qualified).length>=2);await step('mission-won');
