  const fallback=await ctx.newPage();await fallback.addInitScript(()=>Object.defineProperty(window,'Worker',{value:undefined,configurable:true}));await fallback.goto(baseUrl);await fallback.waitForSelector('[data-provider-action="show-new-game"]');await startNew(fallback,{plan:'swift',id:'worker-fallback'});await click(fallback,'[data-provider-action="speed"][data-provider-value="8"]');await fallback.waitForFunction(()=>SCP.state.clock>0,null,{timeout:15000});await click(fallback,'[data-provider-action="pause"]');const tick=await fallback.evaluate(()=>({clock:SCP.state.clock,worker:typeof Worker,locked:SCP.locked,revision:SCP.state.revision}));assert.equal(tick.worker,'undefined');assert.ok(tick.clock>0);row.steps.push({name:'worker-disabled-real-clock-fallback',...tick});await snap(fallback,row,'worker-disabled-real-clock-fallback');
