  await activate('[data-provider-action="drawer"][data-provider-value="deals"]',()=>SOC_PROVIDER_UI.view().drawer==='deals');await activate('[data-provider-action="quote"][data-offer="starter"][data-plan="swift"]',()=>SOC_PROVIDER_UI.view().quoteModal);await page.locator('[data-provider-action="confirm-quote"]:visible').first().waitFor({state:'visible'});await modalCommit();
