async function main(){
 fs.mkdirSync(OUT,{recursive:true});let baseUrl;
 try{report.source=sourceManifest();if(report.source.errors.length)throw new Error('Initial source manifest incomplete: '+JSON.stringify(report.source.errors));baseUrl=await startServer();browser=await playwright[ENGINE].launch({...(BROWSER?{executablePath:BROWSER}:{}),headless:true,...(ENGINE==='chromium'?{args:['--no-sandbox']}:{})});report.browser=browser.version();report.baseUrl=baseUrl;const selected=process.env.SOC_PROVIDER_BROWSER_JOURNEYS?.split(',').map(x=>x.trim()).filter(Boolean);const validJourneys=[...plans.map(x=>x.id),...['enterprise','government','defence'].map(x=>'mission-'+x),'ownership-persistence','keyboard-smb-opening','assurance-quote-preview','mobile-hud-opening','product-retirement','partner-qualification','progression-managed-carrier',...Object.keys(productRecipes).map(x=>'product-'+x)];if(selected?.some(x=>!validJourneys.includes(x)))throw new Error('Unknown selected journey ID');report.selection=selected||'full-matrix';for(const spec of plans.filter(x=>!selected||selected.includes(x.id)))await runJourney(baseUrl,spec);for(const scenario of ['enterprise','government','defence'])if(!selected||selected.includes(`mission-${scenario}`))await runMissionJourney(baseUrl,scenario);if(!selected||selected.includes('ownership-persistence'))await runOwnershipAndPersistence(baseUrl);if(!selected||selected.includes('keyboard-smb-opening'))await runKeyboardJourney(baseUrl);if(!selected||selected.includes('assurance-quote-preview'))await runAssuranceQuoteJourney(baseUrl);if(!selected||selected.includes('mobile-hud-opening'))await runMobileHudJourney(baseUrl);const explicitProducts=process.env.SOC_PROVIDER_BROWSER_PRODUCTS?.split(',').map(x=>x.trim()).filter(Boolean);if(explicitProducts?.some(x=>!productRecipes[x]))throw new Error('Unknown selected product ID');const productSelection=explicitProducts||(!selected?Object.keys(productRecipes):selected.filter(x=>x.startsWith('product-')&&x!=='product-retirement').map(x=>x.slice(8)));for(const recipeId of productSelection)await runProductJourney(baseUrl,recipeId);if(!selected||selected.includes('product-retirement'))await runProductJourney(baseUrl,'ms-workplace-calling',{retirement:true});if(!selected||selected.includes('partner-qualification'))await runQualificationJourney(baseUrl);if(!selected||selected.includes('progression-managed-carrier'))await runProgressionJourney(baseUrl);report.status='passed';}
 catch(error){report.status='failed';report.error=String(error.stack||error);process.exitCode=1;}
 finally{
  for(const [operation,close] of [['browser-close',async()=>{if(browser)await browser.close();}],['server-close',async()=>{if(server?.listening)await new Promise((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}]])try{await close();}catch(error){report.finalizationErrors??=[];report.finalizationErrors.push({operation,error:String(error.stack||error)});if(report.status==='passed')report.status='failed';process.exitCode=1;}
  writeFinalReport();
 }
}
main();
